#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Kanban Autopilot: idea_review által elfogadott ötlet automatikusan
generáljon kanban-kártyát "idea" oszlopba.

Ez a modul figyeli az ötletládát (idea_box), és amikor egy ötlet
idea_review által "accepted" státuszba kerül, automatikusan létrehoz
egy Kanban kártyát az "idea" oszlopban.

Futtatható: python kanban_autopilot.py
"""

import json
import os
import time
import uuid
import hashlib
from datetime import datetime, timezone
from pathlib import Path

# --- Konfiguráció ---
REPO_ROOT = Path(__file__).resolve().parent
IDEA_BOX_DIR = REPO_ROOT / "idea_box"
KANBAN_DIR = REPO_ROOT / "kanban"
KANBAN_BOARD_FILE = KANBAN_DIR / "board.json"
STATE_FILE = REPO_ROOT / "kanban_autopilot_state.json"
POLL_INTERVAL_SEC = 5
IDEA_COLUMN = "idea"


def ensure_dirs():
    """Létrehozza a szükséges könyvtárakat, ha nem léteznek."""
    IDEA_BOX_DIR.mkdir(parents=True, exist_ok=True)
    KANBAN_DIR.mkdir(parents=True, exist_ok=True)


def load_json(path: Path, default):
    """Biztonságos JSON betöltés, default értékkel ha nem létezik."""
    if not path.exists():
        return default
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, OSError):
        return default


def save_json(path: Path, data):
    """JSON mentés atomi módon (tmp + rename)."""
    tmp = path.with_suffix(path.suffix + ".tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    tmp.replace(path)


def load_ideas() -> dict:
    """Betölti az összes ötletet az idea_box könyvtárból.
    Várható formátum: idea_box/<idea_id>.json
    """
    ideas = {}
    if not IDEA_BOX_DIR.exists():
        return ideas
    for p in IDEA_BOX_DIR.glob("*.json"):
        data = load_json(p, None)
        if data and isinstance(data, dict):
            ideas[p.stem] = data
    return ideas


def load_kanban_board() -> dict:
    """Betölti vagy inicializálja a Kanban táblát."""
    board = load_json(KANBAN_BOARD_FILE, None)
    if board is None:
        board = {
            "columns": [
                {"name": "idea", "cards": []},
                {"name": "todo", "cards": []},
                {"name": "doing", "cards": []},
                {"name": "review", "cards": []},
                {"name": "done", "cards": []},
            ],
            "meta": {
                "created": datetime.now(timezone.utc).isoformat(),
                "updated": datetime.now(timezone.utc).isoformat(),
            },
        }
        save_json(KANBAN_BOARD_FILE, board)
    return board


def idea_is_accepted(idea: dict) -> bool:
    """Ellenőrzi, hogy az ötlet idea_review által accepted státuszú-e."""
    review = idea.get("idea_review")
    if isinstance(review, dict):
        status = review.get("status", "").lower()
        return status == "accepted"
    # Alternatív mezőnevek is kezelhetők
    status = idea.get("review_status", idea.get("status", "")).lower()
    return status == "accepted"


def create_kanban_card(idea_id: str, idea: dict) -> dict:
    """Létrehoz egy Kanban kártyát az ötletből."""
    title = idea.get("title", idea.get("name", f"Idea {idea_id}"))
    description = idea.get("description", idea.get("desc", ""))
    submitted_by = idea.get("submitted_by", idea.get("author", "unknown"))
    tags = idea.get("tags", [])
    card_id = "card_" + uuid.uuid4().hex[:12]
    card = {
        "id": card_id,
        "title": title,
        "description": description,
        "column": IDEA_COLUMN,
        "source_idea_id": idea_id,
        "submitted_by": submitted_by,
        "tags": tags if isinstance(tags, list) else [],
        "created": datetime.now(timezone.utc).isoformat(),
        "history": [
            {
                "action": "created",
                "from": "idea_review:accepted",
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "agent": "kanban_autopilot",
            }
        ],
    }
    return card


def add_card_to_board(board: dict, card: dict) -> bool:
    """Hozzáadja a kártyát az 'idea' oszlophoz, ha még nem létezik.
    Visszatér True-val ha hozzáadva, False ha már létezett.
    """
    for col in board.get("columns", []):
        for existing in col.get("cards", []):
            if existing.get("source_idea_id") == card["source_idea_id"]:
                return False
    for col in board.get("columns", []):
        if col.get("name") == IDEA_COLUMN:
            col["cards"].append(card)
            board["meta"]["updated"] = datetime.now(timezone.utc).isoformat()
            return True
    # Ha nincs idea oszlop, létrehozzuk
    board["columns"].insert(0, {"name": IDEA_COLUMN, "cards": [card]})
    board["meta"]["updated"] = datetime.now(timezone.utc).isoformat()
    return True


def load_processed_state() -> dict:
    """Betölti a feldolgozott ötletek állapotát."""
    return load_json(STATE_FILE, {"processed": {}})


def save_processed_state(state: dict):
    """Menti a feldolgozott ötletek állapotát."""
    save_json(STATE_FILE, state)


def process_once() -> list:
    """Egy feldolgozási ciklus: ellenőrzi az ötleteket és létrehozza a kártyákat.
    Visszatér a létrehozott kártyák listájával.
    """
    ensure_dirs()
    ideas = load_ideas()
    board = load_kanban_board()
    state = load_processed_state()
    processed = state.get("processed", {})
    created_cards = []

    for idea_id, idea in ideas.items():
        if not idea_is_accepted(idea):
            continue
        if idea_id in processed and processed[idea_id].get("card_created"):
            continue

        card = create_kanban_card(idea_id, idea)
        added = add_card_to_board(board, card)
        if added:
            save_json(KANBAN_BOARD_FILE, board)
            processed[idea_id] = {
                "card_created": True,
                "card_id": card["id"],
                "processed_at": datetime.now(timezone.utc).isoformat(),
            }
            state["processed"] = processed
            save_processed_state(state)
            created_cards.append(card)
            print(f"[kanban_autopilot] Kártya létrehozva: {card['id']} "
                  f"→ '{card['title']}' (idea: {idea_id})")
        else:
            # Már létezik kártya ehhez az ötlethez
            processed[idea_id] = {
                "card_created": True,
                "card_id": None,
                "note": "already_exists",
                "processed_at": datetime.now(timezone.utc).isoformat(),
            }
            state["processed"] = processed
            save_processed_state(state)

    return created_cards


def run_single_pass():
    """Egyszeri feldolgozás (nem ciklikus)."""
    print("[kanban_autopilot] Egyszeri feldolgozás indul...")
    cards = process_once()
    if not cards:
        print("[kanban_autopilot] Nincs új elfogadott ötlet feldolgozandó.")
    else:
        print(f"[kanban_autopilot] {len(cards)} kártya létrehozva.")
    return cards


def run_daemon(interval: int = POLL_INTERVAL_SEC):
    """Folyamatos figyelés (daemon mód)."""
    print(f"[kanban_autopilot] Daemon indul, poll interval: {interval}s")
    print(f"[kanban_autopilot] idea_box: {IDEA_BOX_DIR}")
    print(f"[kanban_autopilot] kanban:   {KANBAN_BOARD_FILE}")
    try:
        while True:
            process_once()
            time.sleep(interval)
    except KeyboardInterrupt:
        print("\n[kanban_autopilot] Leállítás (Ctrl+C).")


def create_sample_idea(idea_id: str, title: str, description: str,
                       author: str, accepted: bool = True):
    """Segédfüggvény: létrehoz egy minta ötletet idea_box-ban.
    Hasznos teszteléshez.
    """
    ensure_dirs()
    idea = {
        "id": idea_id,
        "title": title,
        "description": description,
        "submitted_by": author,
        "tags": ["autopilot", "test"],
        "created": datetime.now(timezone.utc).isoformat(),
        "idea_review": {
            "status": "accepted" if accepted else "pending",
            "reviewer": "idea_review_agent",
            "reviewed_at": datetime.now(timezone.utc).isoformat(),
        },
    }
    path = IDEA_BOX_DIR / f"{idea_id}.json"
    save_json(path, idea)
    print(f"[kanban_autopilot] Minta ötlet létrehozva: {path}")
    return idea


def main():
    import argparse
    parser = argparse.ArgumentParser(
        description="Kanban Autopilot: elfogadott ötletek → Kanban 'idea' oszlop"
    )
    parser.add_argument(
        "--daemon", action="store_true",
        help="Folyamatos figyelés (polling)"
    )
    parser.add_argument(
        "--interval", type=int, default=POLL_INTERVAL_SEC,
        help="Poll interval másodpercben (daemon mód)"
    )
    parser.add_argument(
        "--once", action="store_true", default=True,
        help="Egyszeri feldolgozás (alapértelmezett)"
    )
    parser.add_argument(
        "--seed", action="store_true",
        help="Minta ötletek létrehozása teszteléshez"
    )
    args = parser.parse_args()

    if args.seed:
        create_sample_idea(
            "idea_e0525cf83577",
            "Koordinált rolling restart",
            "auto_updater.py stagger-elje a node-frissítéseket "
            "(max 1 node/wave), hogy a restart vihar megszűnjön",
            "morzsa",
            accepted=True,
        )
        create_sample_idea(
            "idea_version_drift_heal",
            "Version-drift auto-heal",
            "diagnostics.py 'accepted' státuszú verzió-eltérés "
            "esetén auto-heal javaslatot generáljon",
            "morzsa",
            accepted=True,
        )
        create_sample_idea(
            "idea_pending_example",
            "Minta függőben lévő ötlet",
            "Ez nem kerül Kanban-ra, mert még pending",
            "test",
            accepted=False,
        )
        print("[kanban_autopilot] Minta ötletek seedelve.")

    if args.daemon:
        run_daemon(args.interval)
    else:
        run_single_pass()


if __name__ == "__main__":
    main()